const { trim, truncate } = require('../src/str');

test('trim', () => {
  assert.strictEqual(trim('  a  '), 'a');
});

test('truncate cuts and appends an ellipsis', () => {
  assert.strictEqual(truncate('abcdef', 3), 'abc…');
});

test('truncate leaves short strings alone', () => {
  assert.strictEqual(truncate('abc', 5), 'abc');
});

test('truncate leaves exact-length strings alone', () => {
  assert.strictEqual(truncate('abc', 3), 'abc');
});

test('truncate with n of 0 is just the ellipsis', () => {
  assert.strictEqual(truncate('abc', 0), '…');
});

test('truncate of the empty string is the empty string', () => {
  assert.strictEqual(truncate('', 3), '');
});

